from pathlib import Path

# Channels verified from catalog.get_channels:
# 日漫 (20), 国漫 (21), 剧场 (22), 美漫 (23), 特摄 (25), 少儿 (32), 动态漫 (26), 猜你想看 (27)
class_names = ["日漫", "国漫", "剧场", "美漫", "特摄", "少儿", "动态漫", "猜你想看"]
class_ids = ["20", "21", "22", "23", "25", "32", "26", "27"]

find_rule = """js:
var currentUrl = (typeof MY_URL !== 'undefined' && MY_URL) ? MY_URL : '';
var base = (typeof MY_PARAMS !== 'undefined' && MY_PARAMS && MY_PARAMS.bridgeBase) ? MY_PARAMS.bridgeBase.replace(/\\/$/, '') : 'http://127.0.0.1:18002';
if (base && currentUrl.indexOf('http://127.0.0.1:18002') === 0) {
    currentUrl = currentUrl.replace('http://127.0.0.1:18002', base);
}
if (!currentUrl) {
    var ch = (typeof MY_PARAMS !== 'undefined' && (MY_PARAMS.class || MY_PARAMS.fyclass)) ? (MY_PARAMS.class || MY_PARAMS.fyclass) : '20';
    var pg = (typeof MY_PAGE !== 'undefined' && MY_PAGE) ? MY_PAGE : 1;
    currentUrl = base + '/video_list?channel=' + ch + '&page=' + pg;
}

var resStr = request(currentUrl);
if (!resStr) {
    throw new Error('请求桥接视频列表无响应: ' + currentUrl);
}
var res = JSON.parse(resStr);
if (!res || !res.ok) {
    throw new Error('获取视频列表失败: ' + (res ? res.error : resStr));
}
var items = (res.data && res.data.items) ? res.data.items : [];
var d = [];
for (var i = 0; i < items.length; i++) {
    var it = items[i];
    d.push({
        title: it.name || '',
        desc: it.continu || (it.year ? String(it.year) : ''),
        pic_url: it.pic || '',
        url: base + '/detail?id=' + it.id,
        col_type: 'movie_3'
    });
}
setResult(d);"""

search_find = """js:
var currentUrl = (typeof MY_URL !== 'undefined' && MY_URL) ? MY_URL : '';
var base = (typeof MY_PARAMS !== 'undefined' && MY_PARAMS && MY_PARAMS.bridgeBase) ? MY_PARAMS.bridgeBase.replace(/\\/$/, '') : 'http://127.0.0.1:18002';
if (base && currentUrl.indexOf('http://127.0.0.1:18002') === 0) {
    currentUrl = currentUrl.replace('http://127.0.0.1:18002', base);
}
if (!currentUrl) {
    var kw = (typeof KEYWORD !== 'undefined' && KEYWORD) ? KEYWORD : ((typeof MY_KEYWORD !== 'undefined' && MY_KEYWORD) ? MY_KEYWORD : '');
    var pg = (typeof MY_SEARCH_PAGE !== 'undefined' && MY_SEARCH_PAGE) ? MY_SEARCH_PAGE : ((typeof MY_PAGE !== 'undefined' && MY_PAGE) ? MY_PAGE : 1);
    currentUrl = base + '/search?key=' + encodeURIComponent(kw) + '&page=' + pg;
}

var resStr = request(currentUrl);
if (!resStr) {
    throw new Error('请求桥接搜索接口无响应: ' + currentUrl);
}
var res = JSON.parse(resStr);
if (!res || !res.ok) {
    throw new Error('搜索失败: ' + (res ? res.error : resStr));
}
var items = (res.data && res.data.items) ? res.data.items : [];
var d = [];
for (var i = 0; i < items.length; i++) {
    var it = items[i];
    d.push({
        title: it.name || '',
        desc: it.continu || (it.year ? String(it.year) : ''),
        pic_url: it.pic || '',
        url: base + '/detail?id=' + it.id,
        col_type: 'movie_3'
    });
}
