detail_find_rule = """js:
var currentUrl = (typeof MY_URL !== 'undefined' && MY_URL) ? MY_URL : (typeof input !== 'undefined' ? input : '');
var base = (typeof MY_PARAMS !== 'undefined' && MY_PARAMS && MY_PARAMS.bridgeBase) ? MY_PARAMS.bridgeBase.replace(/\\/$/, '') : 'http://127.0.0.1:18002';
if (base && currentUrl.indexOf('http://127.0.0.1:18002') === 0) {
    currentUrl = currentUrl.replace('http://127.0.0.1:18002', base);
}

var vid = '';
var match = currentUrl.match(/[?&]id=([^&]+)/);
if (match) {
    vid = decodeURIComponent(match[1]);
} else if (/^\\d+$/.test(currentUrl)) {
    vid = currentUrl;
}
if (!vid) {
    throw new Error('详情页未获取到有效视频ID: ' + currentUrl);
}

var detailUrl = base + '/detail?id=' + encodeURIComponent(vid);
var resStr = request(detailUrl);
if (!resStr) {
    throw new Error('请求桥接详情接口无响应: ' + detailUrl);
}
var res = JSON.parse(resStr);
if (!res || !res.ok) {
    throw new Error('获取详情失败: ' + (res ? res.error : resStr));
}
var detail = res.data;
var cleanTitle = detail.name || '';

var d = [];
d.push({
    title: '剧名：' + cleanTitle,
    desc: (detail.continu ? detail.continu + ' ' : '') + (detail.content || ''),
    pic_url: detail.pic || '',
    url: currentUrl,
    col_type: 'pic_1_card'
});

var parts = detail.parts || [];
for (var i = 0; i < parts.length; i++) {
    var group = parts[i];
    var lineName = group.play_zh || group.play || ('线路 ' + (i + 1));
    d.push({
        title: '【' + lineName + '】',
        col_type: 'text_1'
    });
    var epList = group.part || [];
    for (var j = 0; j < epList.length; j++) {
        var epName = epList[j];
        var playParamUrl = base + '/play?id=' + encodeURIComponent(vid) + '&part=' + encodeURIComponent(epName) + '&play=' + encodeURIComponent(group.play);
        d.push({
            title: epName,
            url: playParamUrl + '@lazyRule=.js:(() => { var targetUrl = input; var bridge = (typeof MY_PARAMS !== \"undefined\" && MY_PARAMS && MY_PARAMS.bridgeBase) ? MY_PARAMS.bridgeBase.replace(/\\/$/, \"\") : \"http://127.0.0.1:18002\"; if (bridge && targetUrl.indexOf(\"http://127.0.0.1:18002\") === 0) { targetUrl = targetUrl.replace(\"http://127.0.0.1:18002\", bridge); } var respText = request(targetUrl); if (!respText) throw new Error(\"播放解析无响应: \" + targetUrl); var playObj = JSON.parse(respText); if (!playObj || !playObj.ok) throw new Error(\"播放解析失败: \" + (playObj ? playObj.error : respText)); var pData = playObj.data; var def = pData.default || 0; var variant = (pData.list && pData.list[def]) || (pData.list && pData.list[0]); if (!variant || !variant.url) throw new Error(\"未取得有效直链: \" + respText); var rawUrl = variant.url; var hdrs = variant.headers || {}; var hParts = []; for (var k in hdrs) { if (hdrs.hasOwnProperty(k) && hdrs[k]) { hParts.push(k + \"@\" + hdrs[k]); } } if (hParts.length > 0) { return rawUrl + \";{\" + hParts.join(\"&&\") + \"}\"; } return rawUrl; })()',
            col_type: 'text_3'
        });
    }
}
setResult(d);"""

rule = {
    "title": "动漫共和国概念版",
    "author": "MoZhi",
    "version": 1,
    "url": "http://127.0.0.1:18002/video_list?[REDACTED_QUERY]",
    "col_type": "movie_3",
    "class_name": "&".join(class_names),
    "class_url": "&".join(class_ids),
    "area_name": "",
    "area_url": "",
    "year_name": "",
    "year_url": "",
    "sort_name": "",
    "sort_url": "",
    "find_rule": find_rule,
    "search_url": "http://127.0.0.1:18002/search?[REDACTED_QUERY]",
    "searchFind": search_find,
    "detail_col_type": "movie_1_vertical_pic",
    "detail_find_rule": detail_find_rule
}

out_path = Path("rule.json")
out_path.write_text(json.dumps(rule, ensure_ascii=False, indent=2), encoding="utf-8")
print(f"Generated rule.json successfully, bytes={out_path.stat().st_size}")

